#define main solve_main
#include "solve.cpp"
#undef main
int main(){init();setup();load();atomic<int>job{0};atomic<long long>sum{0},movesum{0};mutex mu;vector<thread>th;for(int w=0;w<4;w++)th.emplace_back([&]{for(;;){int id=job++;if(id>=(int)ts.size())break;auto&t=ts[id];long long n=0,mn=0;for(U a=0;a<(U)t.sz;a++){Pos p=dec(t,a);int z=t.v[a];assert((z!=INV)==valid(t,p));if(z==INV)continue;n++;int best=p.turn?2:-2,total=0;bool live=false;moves(t,p,[&](Move m,Pos v){total++;auto [j,q]=child(t,p,m,v);int x=ts[j].v[enc(ts[j],q)];assert(x!=INV);if(x!=DEAD)live=true;int v2=pc(x)*(q.turn!=1-p.turn?-1:1);if(p.turn)best=min(best,v2);else best=max(best,v2);});mn+=total;bool mate=!total&&att(t,p,p.s[p.turn],1-p.turn,occ(t,p));if(mate)live=true;if(!total)best=mate?(p.turn?1:-1):0;assert(pc(z)==best);assert((z!=DEAD)==live);}sum+=n;movesum+=mn;lock_guard<mutex>lk(mu);cerr<<t.name<<" checked "<<n<<" states "<<mn<<" moves\n";}});for(auto&t:th)t.join();cout<<"AUDIT OK "<<sum<<" states "<<movesum<<" moves\n";}
